from pathlib import Path
import shutil

destinos = {
    ".jpg": "Imagens", ".jpeg": "Imagens", ".png": "Imagens", ".svg": "Imagens",
    ".pdf": "Documentos", ".docx": "Documentos", ".txt": "Documentos", ".md": "Documentos",
    ".xlsx": "Planilhas", ".csv": "Planilhas", ".ods": "Planilhas",
    ".mp3": "Midia", ".mp4": "Midia", ".mov": "Midia",
}

for item in sorted(Path("downloads").iterdir()):
    if item.is_file():
        pasta = Path("downloads") / destinos.get(item.suffix.lower(), "Outros")
        pasta.mkdir(exist_ok=True)
        shutil.move(item, pasta / item.name)

